        bge     bdxe041
        move    a,x0
        bsr     >bdsin
        asl     a
        move    a,x0
        mpy     x0,x0,a  ; B = sin^2, A = cos^2 (amplitudes sum to 1: the heads meet before the expander)
        move    a,x0
        move    x:(r3+$17),b
        sub     b,a
        asr     #$4,a,a
        move    a,x:(r3+$19)
        move    #>$7fffff,a
        sub     x0,a
        move    x:(r3+$16),b
        sub     b,a
        asr     #$4,a,a
        move    a,x:(r3+$18)
        bra     bdfa032
bdxe041:
; crossfade over: B becomes A
        move    x:(r3+$08),a
        move    a,x:(r3+$07)
        move    x:(r3+$05),a
        move    a,x:(r3+$03)
        move    x:(r3+$04),a
        move    a,x:(r3+$02)
        move    x:(r3+$0c),a
        move    a,x:(r3+$0b)
        move    x:(r3+$04),a
        move    a,x:(r3+$29)
        move    #>$7fffff,a
        move    a,x:(r3+$16)
        clr     a
        move    a,x:(r3+$17)
        move    a,x:(r3+$2f)
        move    x:(r3+$27),b
        move    a,x:(r3+$27)
        cmp     #>$3,b
        beq     bdxl042
; after a shortening crossfade: the clock jumps (1/2048 slow: the head can never pass the writer)
        move    x:(r7+$0e),x0
        move    #>$7ff000,y0
        mpy     y0,x0,a
        move    a,x:(r3+$00)
        move    a,x:(r3+$29)
        bsr     >bdnpend
        move    x:(r7+$0e),a
        move    a,x:(r3+$2a)
        bra     bdfa032
bdxl042:
        move    x:(r3+$00),a
        move    a,x:(r3+$2a)
bdfa032:
; writer period: PQ = (1/64)/(c_w/4)
        move    #>$020000,a
        move    x:(r3+$00),x0
        bsr     >bddiv
        move    b,x:(r3+$1d)
; activity: the compressor detector over -72 dBFS (or frozen) keeps the artefacts on; 1.1 s quiet -> off
        move    x:(r3+$2d),a
        add     #>$10,a
        move    #>$00bd8e,x0
        cmp     x0,a
        tgt     x0,a
        move    x:(r3+$0d),b
        move    #>$00020c,x0
        cmp     x0,b
        blt     bdga043
        clr     a
bdga043:
        move    x:(r3+$23),b
        tst     b
        beq     bdgz044
        clr     a
bdgz044:
        move    a,x:(r3+$2d)
        move    #>$00bd7e,x0
        move    #>$7fffff,b
        move    #>$0,y0
        cmp     x0,a
        tgt     y0,b  ; the gate target
        move    x:(r3+$1a),x0
        sub     x0,b
        move    #>$04a4dd,y0
        cmp     y0,b
        tgt     y0,b
        move    #>$fb5b23,y0
        cmp     y0,b
        tlt     y0,b
        move    b,a
        asr     #$4,a,a
        move    a,x:(r3+$1b)
        add     x0,b
        move    b,x:(r3+$1c)
        move    b,x0
        move    #>$00075f,y0
        mpy     y0,x0,a
        move    a,x:(r3+$1e)
        move    #>$000347,y0
        mpy     y0,x0,a
        move    a,x:(r3+$1f)
        move    #>$0013a9,y0
        mpy     y0,x0,a
        move    a,x:(r3+$20)
        neg     a
        move    a,x:(r3+$21)
; feedback gain glides to FDBK (0 while frozen: the plugin cuts the loop)
        move    x:(r7+$04),a
        move    x:(r3+$23),b
        tst     b
        beq     bdkz045
        clr     a
bdkz045:
        move    x:(r3+$24),b
        sub     b,a
        asr     #$3,a,a
        add     a,b
        move    b,x:(r3+$24)
        rts     
bdnpend:
; PCNT = the buckets head A still reads at the old rate = (IW - IA) mod 4096 (0 -> 4096)
        move    x:(r3+$06),a
        move    x:(r3+$07),x0
        sub     x0,a
        sub     #>$1,a
        and     #>$000fff,a
        add     #>$1,a
        move    a1,x:(r3+$28)
        rts     
bdtone:
        move    x:(r7+$01),a
        tst     a
        beq     bdtj046
        move    #>$000000,a
        move    a,x:(r7+$06)
        bsr     >bdsect
        move    #>$000001,a
        move    a,x:(r7+$06)
        bsr     >bdsect
        move    #>$000002,a
        move    a,x:(r7+$06)
        bsr     >bdsect
        move    #>$000003,a
        move    a,x:(r7+$06)
        bsr     >bdsect
        rts     
bdtj046:
        move    x:(r7+$06),a
        add     #>$1,a
        and     #>$3,a
        move    a1,x:(r7+$06)
bdsect:
; h/2 = (hmax/2) 2^-y, y = (127 - TONE)/24 (x 6200/6800 for RC); 1/(2Q); gain; destination
        move    #>$7f0000,a
        move    x:(r7+$05),x0
        sub     x0,a
        move    #>$0,x0
        cmp     x0,a
        tlt     x0,a
        move    a,x0
        move    #>$155555,y0
        mpy     y0,x0,a  ; y/32
        bsr     >bdexp
        move    b,x0
        move    x:(r7+$06),a
        move    #>$439e12,y0
        move    #>$3da6b7,y1
        cmp     #>$2,a
        blt     bdta047
        move    y1,y0
bdta047:
        mpy     y0,x0,a
        move    a,x:(r7+$0f)  ; hh = h/2
; per section: 1/(2Q), the gain (bucketSat slope on AA1), where the five words go
        move    x:(r7+$06),a
        cmp     #>$000000,a
        bne     bdtk048
        move    #>$7684be,x0
        move    x0,x:(r7+$10)
        move    #>$7d1eb8,x0
        move    x0,x:(r7+$11)
        move    r7,b
        add     #>$000013,b
        move    b1,r4
bdtk048:
        cmp     #>$000001,a
        bne     bdtk049
        move    #>$30dadf,x0
        move    x0,x:(r7+$10)
        move    #>$7fffff,x0
        move    x0,x:(r7+$11)
        move    r7,b
        add     #>$000018,b
        move    b1,r4
bdtk049:
        cmp     #>$000002,a
        bne     bdtk050
        move    #>$7684be,x0
        move    x0,x:(r7+$10)
        move    #>$7fffff,x0
        move    x0,x:(r7+$11)
        move    r7,b
        add     #>$00001d,b
        move    b1,r4
bdtk050:
        cmp     #>$000003,a
        bne     bdtk051
        move    #>$30dadf,x0
        move    x0,x:(r7+$10)
        move    #>$7fffff,x0
        move    x0,x:(r7+$11)
        move    r7,b
        add     #>$000022,b
        move    b1,r4
bdtk051:
; S2 = sin(h)/2 = hh (1 - hh^2 (2/3 - hh^2 (2/15 - hh^2 4/315))); C = cos h (series in u = hh^2)
        move    x:(r7+$0f),x0
        mpy     x0,x0,a
        move    a,x1  ; u
        move    #>$01a01a,y0
        mpy     x1,y0,a
        neg     a
        add     #>$111111,a
        move    a,y0
        mpy     x1,y0,a
        neg     a
        add     #>$555555,a
        move    a,y0
        mpy     x1,y0,a
        neg     a
        add     #>$7fffff,a
        move    a,y0
        mpy     y0,x0,a  ; S2 = sin h / 2
        move    a,x:(r7+$12)
; C = 1 - 2u + (2/3)u^2 - (4/45)u^3 + (2/315)u^4
        move    #>$00d00d,y0
        mpy     x1,y0,a
        sub     #>$0b60b6,a
        move    a,y0
        mpy     x1,y0,a
        add     #>$555555,a
        move    a,y0
        mpy     x1,y0,a
        move    a,y0
        mpy     x1,y0,a  ; u (2/3 u - ...)
        move    x1,b
        asl     b  ; 2u
        sub     b,a
        add     #>$7fffff,a  ; C = cos h
        move    a,x0
        move    x0,x:(r7+$0f)  ; (hh no longer needed) C
; P = S2 C = sin(w)/4; al = P (2/Q) = (P/(2Q)) 4; cos w = C^2 - 4 S2^2; s2 = sin^2 h = 4 S2^2
        move    x:(r7+$12),y0
        mpy     y0,x0,a
        move    a,x1  ; P
        move    x:(r7+$10),y0
        mpy     x1,y0,a
        asl     #$2,a,a  ; al
        move    a,x:(r7+$10)  ; (1/(2Q) no longer needed) al
        add     #>$7fffff,a
        asr     a  ; (1 + al)/2
        move    a,y1
        move    #>$200000,a
        move    y1,x0
        bsr     >bddiv  ; b = nh = n/2 = 0.5/(1 + al)
        move    b,y1  ; nh
        move    x:(r7+$12),x0
        mpy     x0,x0,a
        asl     #$2,a,a
        move    a,x1  ; s2 = sin^2 h
        move    x:(r7+$0f),x0
        mpy     x0,x0,b  ; C^2
        sub     a,b  ; cos w = C^2 - s2
        move    b,x0
        mpy     x0,y1,b  ; cos w n/2
        asl     b
        neg     b
        move    b,x:(r4+$3)  ; A1/2 = -cos w n
        move    #>$7fffff,b
        move    x:(r7+$10),x0
        sub     x0,b
        move    b,x0
        mpy     x0,y1,b  ; A2/2 = (1 - al) n/2
        move    b,x:(r4+$4)
        move    x1,x0
        mpy     x0,y1,b  ; s2 n/2 = b0/2
        move    b,x0
        move    x:(r7+$11),y0
        mpy     y0,x0,b  ; x the section gain
        move    b,x:(r4)
        move    b,x:(r4+$2)
        asl     b
        move    b,x:(r4+$1)  ; B1/2 = b0
        rts     
bdexp:
        move    a1,b
        asr     #$12,a,a  ; a1 = n = floor(y)
        add     #>$1,a
        move    a1,x1  ; n + 1 (never 0: a do count of 0 is not a skip)
        and     #>$03ffff,b
        asl     #$5,b,b  ; f in Q23, b2 stays 0
        move    b1,x0
        move    #>$2c5c86,y0
        mpy     y0,x0,b
        move    b,y0  ; g = f ln2 / 2
        move    #>$02aaab,x0
        mpy     y0,x0,b
        sub     #>$0aaaab,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$200000,b
        move    b,x0
        mpy     y0,x0,b
        sub     #>$400000,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$400000,b  ; e^-g / 2
        move    b,x0
        mpy     x0,x0,b
        asl     #$2,b,b  ; 2^-f in (0.5, 1]
        do      x1,>bdxpend
        asr     b
bdxpend:
        asl     b
        rts     
bddiv:
; a1 / x0 (0 <= a1 < x0) -> b (Q23)
        move    a1,a
        andi    #$fe,ccr
        do      #24,>bddvend
        div     x0,a
bddvend:
        nop     
        move    a0,b
        rts     
bdsin:
; a = sin(pi x0 / 2) / 2 for x0 in [-1, 1] (odd quintic); clobbers x1 y0
        mpy     x0,x0,a
        move    a,x1
        move    #>$04a277,y0
        mpy     x1,y0,a
        add     #>$d6de19,a
        move    a,y0
        mpy     x1,y0,a
        add     #>$648200,a
        move    a,y0
        mpy     y0,x0,a
        rts     
